const iconPool: { [key: string]: Icon } = {};
function getIcon(url: string) {
  if (!iconPool[url]) {
    iconPool[url] = new Icon(url); // heavy immutable data
  }
  return iconPool[url];
}
class Icon { constructor(public url: string) {} }

class Glyph {
  char: string;
  x = 0;
  y = 0;
  draw(ctx: any, x: number, y: number) {
    this.x = x;
    this.y = y;
    ctx.drawText(this.char, this.x, this.y);
  }
}
const factory = new Map<string, Glyph>();
function glyphFor(c: string) {
  if (!factory.has(c)) factory.set(c, new Glyph());
  return factory.get(c)!;
}

